const rows = $input.all();
const blockedCompanies = [];
const blockedKeywords = [];
const scamKeywords = [];

for (const row of rows) {
  const r = row.json;
  if (String(r.active || 'yes').toLowerCase().trim() === 'no') continue;

  const value = String(r.company_name || r.value || r.name || '').trim().toLowerCase();
  const type = String(r.type || 'company').trim().toLowerCase();
  if (!value) continue;

  if (type === 'company') blockedCompanies.push(value);
  else if (type === 'keyword') blockedKeywords.push(value);
  else if (type === 'scam_phrase' || type === 'scam') scamKeywords.push(value);
}

const envBlocked = String(process.env.BLOCKED_COMPANIES || '')
  .split(',')
  .map(s => s.trim().toLowerCase())
  .filter(Boolean);

return [{
  json: {
    blockedCompanies: [...new Set([...blockedCompanies, ...envBlocked])],
    blockedKeywords: [...new Set(blockedKeywords)],
    scamKeywords: [...new Set(scamKeywords)],
    loadedAt: new Date().toISOString()
  }
}];

const response = $input.first().json;
const jobs = response.jobs || [];

if (!jobs.length) {
  return [{ json: { _empty: true, search_summary: response } }];
}

return jobs.map(job => ({
  json: {
    ...job,
    search_summary: {
      total_found: response.total_found,
      new_jobs: response.new_jobs,
      cached_skipped: response.cached_skipped,
      queries_run: response.queries_run,
      duration_ms: response.duration_ms
    }
  }
}));

const apiKey = process.env.OPENROUTER_API_KEY;
const model = process.env.OPENROUTER_MODEL || 'openai/gpt-oss-120b:free';
const blocklist = $('Build Blocklist Arrays').first().json;
const blockedCompanies = blocklist.blockedCompanies || [];
const blockedKeywords = blocklist.blockedKeywords || [];
const scamKeywords = blocklist.scamKeywords || [];
const results = [];

function normalizeTags(tags) {
  if (Array.isArray(tags)) return tags.map(String).filter(Boolean);
  if (typeof tags === 'string') return tags.split(',').map(s => s.trim()).filter(Boolean);
  return [];
}

function fallback(job, reason) {
  const text = `${job.title || ''} ${job.company || ''} ${job.description || ''}`.toLowerCase();
  const isBlocked = blockedCompanies.some(c => text.includes(c)) || blockedKeywords.some(k => text.includes(k));
  return {
    ...job,
    ai_is_scam: false,
    ai_is_blocked: isBlocked,
    ai_relevance_score: Number(job.score || 0),
    ai_reason: reason,
    ai_tags: normalizeTags(job.tags || [job.source, job.location]).join(', ')
  };
}

for (const item of $input.all()) {
  const job = item.json;
  if (!apiKey || apiKey === 'replace_me') {
    results.push({ json: fallback(job, 'OPENROUTER_API_KEY is not configured') });
    continue;
  }

  const prompt = `You are a job filter. Given this job posting, respond ONLY with valid JSON.\n\nJob title: ${job.title || ''}\nCompany: ${job.company || ''}\nDescription: ${String(job.description || '').substring(0, 1200)}\n\nBlocked companies list: ${blockedCompanies.join(', ')}\nBlocked keywords: ${blockedKeywords.join(', ')}\nScam phrases: ${scamKeywords.join(', ')}\n\nReturn:\n{\n  "is_scam": true/false,\n  "is_blocked": true/false,\n  "relevance_score": 0-10,\n  "reason": "brief reason",\n  "tags": ["devops", "remote", "contract"]\n}\n\nScam signals: vague pay, MLM language, "be your own boss", no company info, requests upfront payment, unrealistic salary, fake recruiter patterns.\n\nTarget profile: DevOps, Backend, Cloud, Platform, Full Stack, Python/FastAPI, Go, AWS, Terraform, Kubernetes, React, CI/CD, remote/contract/full-time.`;

  try {
    const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': 'https://n8n.io',
        'X-Title': 'Job Automation v3'
      },
      body: JSON.stringify({
        model,
        temperature: 0.1,
        max_tokens: 300,
        messages: [
          { role: 'system', content: 'You are a job filter. Return only valid JSON. No markdown.' },
          { role: 'user', content: prompt }
        ]
      })
    });

    if (!response.ok) throw new Error(`OpenRouter HTTP ${response.status}`);
    const data = await response.json();
    const content = data.choices?.[0]?.message?.content || '{}';
    const jsonText = content.replace(/```json|```/g, '').trim();
    const ai = JSON.parse(jsonText);

    results.push({ json: {
      ...job,
      ai_is_scam: ai.is_scam === true,
      ai_is_blocked: ai.is_blocked === true,
      ai_relevance_score: Math.max(0, Math.min(10, Number(ai.relevance_score || 0))),
      ai_reason: String(ai.reason || ''),
      ai_tags: normalizeTags(ai.tags).join(', ')
    }});
  } catch (error) {
    results.push({ json: fallback(job, `AI request/parse failed: ${error.message}`) });
  }
}

return results;

function escapeMarkdown(text) {
  return String(text || '').replace(/([_*[\]()~`>#+\-=|{}.!])/g, '\\$1');
}

return $input.all().map(item => {
  const j = item.json;
  const score = Number(j.ai_relevance_score || 0);
  const tags = String(j.ai_tags || '')
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
  const emoji = score >= 8 ? '🔥' : score >= 6 ? '✅' : '📌';
  const title = escapeMarkdown(j.title);
  const company = escapeMarkdown(j.company);
  const location = escapeMarkdown(j.location || 'Remote');
  const salary = escapeMarkdown(j.salary || 'Not specified');
  const tagText = escapeMarkdown(tags.length ? tags.join(' · ') : j.source || 'job');
  const posted = escapeMarkdown(j.posted_at || new Date().toISOString());
  const url = String(j.url || '').replace(/\)/g, '%29');

  const telegram_message = `${emoji} *${title}*\n🏢 ${company}\n📍 ${location}\n💰 ${salary}\n🏷️ ${tagText}\n⭐ Relevance: ${score}/10\n\n🔗 [View Job](${url})\n📅 ${posted}`;
  return { json: { ...j, telegram_message } };
});
